/**
 * weaponSkillCaps.js
 * Player skill caps per class and level, read from the Quarm server's skill_caps table.
 *
 * The exact per-level values live in skillCapsData.js (generated by scripts/skill-caps-to-js.mjs from the
 * server SQL). This file only looks them up the way the server does (common/skill_caps.cpp):
 *   - a level below the class's first row for the skill means the class doesn't have the skill yet -> 0
 *   - a level above the last row uses the last row (server GetSkillCapMaxLevel); the rule maximum is 65
 * Load skillCapsData.js first, then this file; exposes global WeaponSkillCaps.
 */
(function (global) {
  'use strict';

  const SKILL_CAP_MAX_LEVEL = 65; // Character:SkillCapMaxLevel rule on Quarm
  const DATA = (global.SkillCapsData && global.SkillCapsData.skills) || null;
  if (!DATA && typeof console !== 'undefined') {
    console.error('weaponSkillCaps.js: skillCapsData.js is not loaded; every skill cap will read as 0.');
  }

  const CLASS_ORDER = [
    'WAR', 'CLR', 'PAL', 'RNG', 'SHD', 'DRU', 'MNK', 'BRD', 'ROG', 'SHM', 'NEC', 'WIZ', 'MAG', 'ENC', 'BST'
  ];

  /** Exact server cap for skill `key` (a key of skillCapsData.js) at `level`; 0 if the class lacks it at that level. */
  function lookupCap(key, clsIndex, level) {
    const rows = DATA && DATA[key] && DATA[key][clsIndex];
    if (!rows) return 0;
    const first = rows[0];
    const lvl = Math.min(SKILL_CAP_MAX_LEVEL, Math.floor(level));
    if (!(lvl >= first)) return 0;
    const last = first + rows.length - 2;
    return rows[Math.min(lvl, last) - first + 1];
  }

  /** Level the class first gets the skill (server GetSkillTrainLevel); 0 = never. */
  function lookupTrainLevel(key, clsIndex) {
    const rows = DATA && DATA[key] && DATA[key][clsIndex];
    return rows ? rows[0] : 0;
  }

  /** Highest cap the class ever reaches in the skill (its value at the rule max level). */
  function maxCapRow(key) {
    return CLASS_ORDER.map(function (_, c) { return lookupCap(key, c, SKILL_CAP_MAX_LEVEL); });
  }

  const SkillCapsSpec = {
    meta: {
      ruleset: 'Project Quarm (server skill_caps table)',
      levelMin: 1,
      levelMax: SKILL_CAP_MAX_LEVEL
    },
    classes: CLASS_ORDER,
    skills: ['1hb', '1hs', '1hp', '2hb', '2hs', 'h2h', 'archery', 'throwing'],
    // Class maximums at the rule max level (65). Informational; level-by-level values come from lookupCap.
    maxCaps: {}
  };
  SkillCapsSpec.skills.forEach(function (k) { SkillCapsSpec.maxCaps[k] = maxCapRow(k); });

  /** Offense, Dual Wield, Double Attack class maximums (0 = class doesn't have the skill). */
  const CombatSkillCaps = {
    offense: maxCapRow('offense'),
    dualWield: maxCapRow('dualWield'),
    doubleAttack: maxCapRow('doubleAttack')
  };

  /** Defense, Dodge, Riposte, Block, Parry class maximums at the rule max level. */
  const DefensiveSkillCaps = {
    defense: maxCapRow('defense'),
    dodge: maxCapRow('dodge'),
    riposte: maxCapRow('riposte'),
    block: maxCapRow('block'),
    parry: maxCapRow('parry')
  };

  /** Level each class first gets the defensive skill (0 = can never learn it). */
  const DefensiveSkillTrainLevels = {};
  ['defense', 'dodge', 'riposte', 'block', 'parry'].forEach(function (k) {
    DefensiveSkillTrainLevels[k] = CLASS_ORDER.map(function (_, c) { return lookupTrainLevel(k, c); });
  });

  /** Sim classId (e.g. "warrior", "monk") -> spec class index 0..14 */
  const SIM_CLASS_TO_INDEX = {
    warrior: 0,      cleric: 1,    paladin: 2,    ranger: 3,    shadowknight: 4,
    druid: 5,        monk: 6,      bard: 7,        rogue: 8,     shaman: 9,
    necromancer: 10, wizard: 11,   magician: 12,   enchanter: 13, beastlord: 14
  };

  /**
   * Resolve classId to spec class index.
   * @param {Object} spec - SkillCapsSpec
   * @param {number|string} classId - 0..14, "WAR", or "warrior"
   * @returns {number} 0..14 or -1 if unknown
   */
  function resolveClassIndex(spec, classId) {
    spec = spec || SkillCapsSpec;
    if (typeof classId === 'number') {
      return classId >= 0 && classId < spec.classes.length ? classId : -1;
    }
    const s = String(classId).toLowerCase();
    if (SIM_CLASS_TO_INDEX[s] !== undefined) return SIM_CLASS_TO_INDEX[s];
    const idx = spec.classes.indexOf(String(classId).toUpperCase());
    return idx >= 0 ? idx : -1;
  }

  /**
   * Exact server cap for any skill in skillCapsData.js.
   * @param {string} skillKey - e.g. "1hb", "h2h", "archery", "offense", "dodge", "backstab", "kick"
   * @param {number|string} classId - class index 0..14, "WAR", or "warrior"
   * @param {number} level
   * @returns {number}
   */
  function getSkillCap(skillKey, classId, level) {
    const clsIndex = resolveClassIndex(SkillCapsSpec, classId);
    if (clsIndex < 0) return 0;
    return lookupCap(skillKey, clsIndex, level);
  }

  /** Weapon skill cap for a class/skill/level (kept for existing callers; `spec` is ignored). */
  function getWeaponSkillCap(spec, classId, skillKey, level) {
    return getSkillCap(skillKey, classId, level);
  }

  /**
   * Prebuild table: table[skillKey][classIndex][level] => cap.
   * @returns {Object}
   */
  function buildWeaponSkillCapTable() {
    const out = {};
    SkillCapsSpec.skills.forEach(function (skillKey) {
      out[skillKey] = CLASS_ORDER.map(function (_, c) {
        const row = new Array(SKILL_CAP_MAX_LEVEL + 1).fill(0);
        for (let lvl = 1; lvl <= SKILL_CAP_MAX_LEVEL; lvl++) row[lvl] = lookupCap(skillKey, c, lvl);
        return row;
      });
    });
    return out;
  }

  /** Convenience: cap using sim classId string and weapon skill key. (`spec` is ignored.) */
  function getCapForSimClass(classId, skillKey, level) {
    return getSkillCap(skillKey, classId, level);
  }

  /** Offense, Dual Wield, Double Attack cap for class/level ("offense" | "dualWield" | "doubleAttack"). */
  function getCombatSkillCap(combatSkillKey, classId, level) {
    return getSkillCap(combatSkillKey, classId, level);
  }

  /**
   * Defense, Dodge, Parry, Riposte, Block cap for class/level. 0 if the class can't learn the skill or
   * hasn't reached the level it is first trained.
   */
  function getDefensiveSkillCap(defSkillKey, classId, level) {
    return getSkillCap(defSkillKey, classId, level);
  }

  global.WeaponSkillCaps = {
    SkillCapsSpec: SkillCapsSpec,
    CombatSkillCaps: CombatSkillCaps,
    DefensiveSkillCaps: DefensiveSkillCaps,
    DefensiveSkillTrainLevels: DefensiveSkillTrainLevels,
    getSkillCap: getSkillCap,
    getWeaponSkillCap: getWeaponSkillCap,
    buildWeaponSkillCapTable: buildWeaponSkillCapTable,
    getCapForSimClass: getCapForSimClass,
    getCombatSkillCap: getCombatSkillCap,
    getDefensiveSkillCap: getDefensiveSkillCap,
    resolveClassIndex: resolveClassIndex,
    SIM_CLASS_TO_INDEX: SIM_CLASS_TO_INDEX
  };
})(typeof self !== 'undefined' ? self : this);
